from taf.ul.kpi_selector.operations.operation_prototype.operation_prototype import OperationPrototype


class SnapshotCollection(OperationPrototype):
    def __init__(self, bts):
        super(SnapshotCollection, self).__init__(bts)
        self.operation_details = {
            "Timeout": 840,
            "Operation": "Manually Triggered On-Demand Full Coverage Snapshot",
            "Start point": "Moment of receiving the snapshot collection request",
            "End point": "Moment of sending the last response or file",
            "Requirement": "OM_GEN_SFS_PERF_CAP.2836",
        }

    def get_kpi(self, coverage):
        """
        Gets Manually Triggered On-Demand Snapshot timeout
        KPI: Troubleshooting Data Collection Duration - Manually Triggered On-Demand Snapshot
        Requirement: OM_GEN_SFS_PERF_CAP.2836
        """
        if coverage.lower() != "full":

            self.operation_details["Operation"] = "Manually Triggered On-Demand Minor Snapshot"
            self.operation_details["Requirement"] = "There is no requirement in Gates tool for Minor Snapshot. " \
                                                    "Timeout used has the same value as for full coverage snapshot."

        return self.operation_details
